-- Name: discovery_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.discovery_view WITH (security_barrier='true') AS
 SELECT id,
    username,
    avatar_url,
    interest_tags
   FROM public.users
  WHERE ((deleted_at IS NULL) AND (discovery_opt_in = true) AND (interest_tags <> '{}'::text[]) AND (NOT (EXISTS ( SELECT 1
           FROM public.friendships
          WHERE ((friendships.status = 'blocked'::public.friendship_status) AND (((friendships.requester_id = users.id) AND (friendships.addressee_id = auth.uid())) OR ((friendships.requester_id = auth.uid()) AND (friendships.addressee_id = users.id))))))));


--

-- Name: user_search_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_search_view WITH (security_barrier='true') AS
 SELECT id,
    username,
    avatar_url,
    bio
   FROM public.users
  WHERE ((deleted_at IS NULL) AND (NOT (EXISTS ( SELECT 1
           FROM public.friendships
          WHERE ((friendships.status = 'blocked'::public.friendship_status) AND (((friendships.requester_id = users.id) AND (friendships.addressee_id = auth.uid())) OR ((friendships.requester_id = auth.uid()) AND (friendships.addressee_id = users.id))))))));


